insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000019', 'en', null, 'Introduction to Law & Legal Literacy', 'A plain-language tour of how law actually works — where rules come from, how courts resolve disputes, and the everyday reach of contracts, torts, and criminal vs. civil law. Structure adapted from OpenStax Business Law I Essentials (CC BY 4.0). This is a general legal-literacy course, not legal advice; laws vary by country, state, and situation, so consult a licensed lawyer for any real decision.', null, 'foundations', 25, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000019', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In most common-law countries, ''law'' is best described as…","options":["only what the police enforce","a system of enforceable rules from several sources","whatever a judge feels is fair","the same in every country"],"answer":1,"explanation":"Law is a system of binding rules drawn from constitutions, statutes, and court decisions — and it varies by place."},{"prompt":"A rule passed by a legislature (like Congress or Parliament) is called a…","options":["precedent","statute","regulation","verdict"],"answer":1,"explanation":"Statutes are written laws enacted by a legislature."},{"prompt":"''Common law'' primarily refers to…","options":["laws everyone knows","law built from past court decisions (precedent)","international treaties","local town rules"],"answer":1,"explanation":"Common law develops through judicial decisions that later courts follow."},{"prompt":"A dispute between two private parties over money owed is usually a…","options":["criminal case","civil case","constitutional case","regulatory hearing"],"answer":1,"explanation":"Civil law resolves disputes between private parties; criminal law is the state prosecuting an offense."},{"prompt":"For most contracts to form, you generally need offer, acceptance, and…","options":["a notary","consideration (something of value exchanged)","a lawyer present","a written page"],"answer":1,"explanation":"Consideration — the bargained-for exchange — is a core element in common-law contract formation."},{"prompt":"Accidentally injuring someone through carelessness is most associated with…","options":["a breach of contract","negligence (a tort)","a felony","arbitration"],"answer":1,"explanation":"Negligence is a tort — a civil wrong involving a failure to use reasonable care."},{"prompt":"In a criminal case, the case is typically brought by…","options":["the injured person","the government / state","an insurance company","a jury"],"answer":1,"explanation":"Criminal cases are prosecuted by the state on behalf of the public."},{"prompt":"Which statement about this course is correct?","options":["It gives legal advice for your situation","It teaches general legal literacy and laws vary by place","It applies identically worldwide","It replaces a lawyer"],"answer":1,"explanation":"This is general legal literacy — not advice — and laws differ by jurisdiction."}]}'::jsonb, null, 10),
  (2, 'What law is and where it comes from', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main sources of law and explain how they rank. Warm-up: from the diagnostic, what is the difference between a *statute* and *common law*?"},{"heading":"The idea","text":"Real scenario: you buy a phone online, it never arrives, and the seller ignores you. Which rules decide what happens? In common-law systems there are layers. A *constitution* is the highest law and sets the framework. *Statutes* are written laws passed by a legislature. *Regulations* are detailed rules issued by agencies under a statute''s authority. *Common law* is the accumulated body of court decisions, where judges follow *precedent* — earlier rulings on similar facts. When these conflict, the higher source wins: a statute cannot override the constitution, and a regulation cannot exceed its statute. Crucially, *jurisdiction* determines whose law applies — the answer for that phone can differ by country and even by state or province."},{"heading":"Worked example","text":"Reasoning through a case: a state passes a statute banning a certain additive in food sold there. A company argues the ban conflicts with its constitutional free-trade rights. A court must (1) identify the sources in play — statute vs. constitution — (2) apply the ranking, since the constitution outranks the statute, and (3) decide whether the statute actually violates a constitutional protection or is a valid exercise of the state''s power to protect health. The court reasons from precedent — how similar bans were treated before — rather than from personal opinion."},{"heading":"Your turn","text":"Classify each source: (1) a rule a legislature votes into law, (2) the supreme framework all other law must respect, (3) a judge-made rule from following past decisions, (4) a detailed agency rule enforcing a statute, (5) the principle that decides which place''s law applies. Answers: (1) statute, (2) constitution, (3) common law / precedent, (4) regulation, (5) jurisdiction."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a statute can override the constitution — it cannot. Mistake: assuming law is identical everywhere — it varies by jurisdiction. Exit: (a) Which source is highest? (b) What is precedent? Answers: the constitution; a past court decision that guides later similar cases."}]}'::jsonb, 'Sources rank: constitution > statute > regulation; common law fills the gaps. Jurisdiction = whose rules apply.', 12),
  (3, 'The court system and how a case works', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the path of a case from filing to appeal and name who must prove what. Warm-up: who brings a criminal case — the victim or the state?"},{"heading":"The idea","text":"Real scenario: a neighbor''s contractor damages your fence and refuses to pay. How does a dispute become a decision? Most systems have *trial courts* that hear evidence and find facts, and *appellate (appeals) courts* that review whether the law was applied correctly — they generally do not re-hear witnesses. The party who starts a civil case is the *plaintiff*; the one who responds is the *defendant*. In criminal matters the *prosecution* (the state) charges a defendant. The *burden of proof* differs sharply: in most civil cases the plaintiff must show their claim is more likely true than not (the *balance of probabilities* / *preponderance of the evidence*), while criminal guilt must be proven *beyond a reasonable doubt* — a much higher bar. Many disputes settle or go to *mediation* or *arbitration* before any trial."},{"heading":"Worked example","text":"Reasoning through a case: the fence dispute goes to a small-claims trial court. You (plaintiff) present the repair invoice and photos; the contractor (defendant) disputes the cost. The judge weighs the evidence and finds it *more likely than not* that the contractor caused the damage — meeting the civil standard — and orders payment. The contractor appeals, arguing the judge used the wrong measure of damages. The appeals court does not re-examine the photos; it only checks whether the *legal rule* for damages was applied correctly. That division of labor — facts below, law above — is the heart of how courts work."},{"heading":"Your turn","text":"Answer each: (1) Which court finds the facts? (2) Which reviews the law? (3) Who starts a civil case? (4) What standard proves a crime? (5) Name one alternative to a trial. (6) In a civil case, what is the plaintiff''s standard? Answers: (1) trial court, (2) appellate court, (3) the plaintiff, (4) beyond a reasonable doubt, (5) mediation or arbitration (settlement), (6) balance of probabilities / preponderance of the evidence."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking an appeal is a fresh trial with new witnesses — it usually reviews only legal errors. Mistake: applying the criminal ''beyond reasonable doubt'' standard to a civil suit. Exit: (a) Civil burden of proof? (b) Who prosecutes a crime? Answers: balance of probabilities; the state / prosecution."}]}'::jsonb, 'Trial court finds facts; appeals court reviews the law. Burden of proof differs: civil = balance of probabilities; criminal = beyond reasonable doubt.', 13),
  (4, 'Contracts: how promises become binding', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify the elements that form a contract and what happens when one is broken. Warm-up: besides offer and acceptance, what third element do common-law contracts usually need?"},{"heading":"The idea","text":"Real scenario: a freelancer agrees by email to design a logo for $400, delivers it, and the client refuses to pay. Is there a binding contract? In common-law systems a contract generally needs an *offer*, an *acceptance* of that offer, and *consideration* — something of value exchanged by each side. Courts also look for an *intention to create legal relations*, *capacity* (the parties are legally able to contract), and a *lawful purpose*. A *breach* is a failure to perform a contractual duty. The usual remedy is *damages* — money to put the wronged party where performance would have — and occasionally *specific performance*, a court order to actually do what was promised. Some contracts (for example, sales of land) must be in writing to be enforceable, but many spoken and emailed deals are fully binding."},{"heading":"Worked example","text":"Reasoning through a case: apply the elements to the logo deal. Offer: the client asked for a logo at a stated price. Acceptance: the freelancer agreed by email. Consideration: design work in exchange for $400 — value both ways. Intention and legality are present, and both parties have capacity. So a contract formed. The client''s refusal to pay is a *breach*. Remedy: the freelancer is owed the $400 in *damages*, the benefit they bargained for. The medium being email, not paper, does not defeat the contract in most jurisdictions."},{"heading":"Your turn","text":"For each, name the missing or present element: (1) ''I''ll sell you my bike for $50'' — ''Deal.'' (2) A promise to give a pure gift, nothing given back. (3) A signed deal to do something illegal. (4) A minor far below the age of capacity signs a phone plan. (5) A party performs, the other refuses to pay. Answers: (1) offer + acceptance + consideration — valid; (2) no consideration — generally unenforceable as a contract; (3) no lawful purpose — void; (4) lacks capacity — may be voidable; (5) breach — remedy is damages."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing a contract must be a signed paper — many oral and electronic agreements bind. Mistake: assuming every broken promise is a lawsuit; small breaches often resolve by negotiation, and rules vary by jurisdiction. Exit: (a) Name the three core formation elements. (b) The usual remedy for breach? Answers: offer, acceptance, consideration; damages (money)."}]}'::jsonb, 'Offer + acceptance + consideration (+ intent + capacity + legality) = a contract. Breach → remedies, usually damages.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which source of law is highest?","options":["a regulation","a statute","the constitution","common law"],"answer":2,"explanation":"The constitution outranks statutes, regulations, and common law."},{"prompt":"''Precedent'' means…","options":["a new statute","a past court decision guiding later cases","an agency rule","a jury''s verdict"],"answer":1,"explanation":"Common law follows precedent — earlier rulings on similar facts."},{"prompt":"A trial court mainly…","options":["reviews legal errors","finds the facts and hears evidence","writes statutes","issues regulations"],"answer":1,"explanation":"Trial courts find facts; appellate courts review the law."},{"prompt":"The standard of proof in a criminal case is…","options":["balance of probabilities","beyond a reasonable doubt","more likely than not","clear preference"],"answer":1,"explanation":"Criminal guilt must be proven beyond a reasonable doubt."},{"prompt":"The three core elements to form a contract are offer, acceptance, and…","options":["a signature","consideration","a witness","a court filing"],"answer":1,"explanation":"Consideration is the bargained-for exchange of value."},{"prompt":"The usual remedy for breach of contract is…","options":["jail","damages (money)","deportation","a criminal record"],"answer":1,"explanation":"Breach is a civil matter; the standard remedy is monetary damages."}]}'::jsonb, null, 8),
  (6, 'Torts and liability basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a tort is and walk through the elements of negligence. Warm-up: is carelessly injuring someone a crime, a breach of contract, or something else?"},{"heading":"The idea","text":"Real scenario: a café mops its floor, leaves no warning sign, and a customer slips and breaks a wrist. No contract was broken and no crime charged — yet the customer may recover money. That is *tort law*: civil wrongs that cause harm, where the remedy is usually *damages*. The most common tort is *negligence*, which classically has four elements: a *duty of care* owed to the person, a *breach* of that duty (falling below the reasonable standard), *causation* (the breach actually caused the harm), and *damages* (real harm resulted). Torts also include *intentional* wrongs (like defamation) and, in some areas, *strict liability*, where a party is liable for certain harms even without fault — for example, some defective-product claims. *Liability* simply means legal responsibility to answer for the harm."},{"heading":"Worked example","text":"Reasoning through a case: apply the four elements to the café slip. Duty: a business owes customers a duty to keep premises reasonably safe. Breach: mopping without a warning sign falls below that standard. Causation: the wet, unmarked floor caused the fall — and it wouldn''t have happened otherwise. Damages: a broken wrist is real harm with real costs. All four are met, so the café is likely *liable* in negligence. Note the reasoning is about a *reasonable* standard, not perfection — and outcomes and defenses (like the customer''s own carelessness) vary by jurisdiction."},{"heading":"Your turn","text":"Identify which negligence element is missing or present: (1) a driver owes other road users care. (2) Someone is careless but no one is harmed at all. (3) A shop spills oil, ignores it, and a shopper falls and is injured. (4) A harm happened, but a totally unrelated event, not the defendant, caused it. (5) A product is defective and injures a user with no proof of carelessness. Answers: (1) duty — present; (2) no damages — no negligence claim; (3) all four present — likely liable; (4) no causation — claim fails; (5) may be strict liability — fault not required."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing a tort with a crime — the same act can be both, but a tort is a private civil claim for damages. Mistake: thinking any injury automatically means liability; without a breached duty and causation there is no negligence. Exit: (a) Name the four elements of negligence. (b) What does ''liability'' mean? Answers: duty, breach, causation, damages; legal responsibility for the harm."}]}'::jsonb, 'Negligence = duty + breach + causation + harm. A tort is a civil wrong, separate from a crime or a contract.', 13),
  (7, 'Criminal vs. civil law', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish criminal from civil law by who sues, what''s at stake, and the proof required. Warm-up: if someone punches you, could there be both a criminal case and a civil case?"},{"heading":"The idea","text":"Real scenario: a driver runs a red light and injures a cyclist. Two separate legal tracks can open. *Criminal law* concerns offenses against society; the *state* prosecutes, the aim is *punishment* (fines, probation, imprisonment), and guilt must be proven *beyond a reasonable doubt*. *Civil law* concerns private disputes; the *injured party* sues, the aim is a *remedy* — usually *compensation* — and the standard is the lower *balance of probabilities*. The same act can produce both: the state may prosecute the driver for reckless driving while the cyclist separately sues for damages. Because the standards differ, someone can be acquitted of a crime yet still be found liable in a civil suit on the same facts. Which offenses exist and how they''re punished vary widely by jurisdiction."},{"heading":"Worked example","text":"Reasoning through a case: sort the red-light collision into both tracks. Criminal track: the *state* charges the driver; if guilt is shown *beyond a reasonable doubt*, the penalty is punishment such as a fine or license loss. Civil track: the *cyclist* sues the driver; if it is *more likely than not* that the driver''s carelessness caused the injury, the driver pays *compensation*. Notice how the labels line up — plaintiff/prosecution, compensation/punishment, low bar/high bar — and how one event feeds two independent proceedings with different goals."},{"heading":"Your turn","text":"Label each as criminal or civil: (1) the government charges someone with theft. (2) A landlord sues a tenant for unpaid rent. (3) A prosecutor must prove guilt beyond a reasonable doubt. (4) A plaintiff seeks money to cover medical bills. (5) The aim is to punish an offense against society. Answers: (1) criminal, (2) civil, (3) criminal, (4) civil, (5) criminal."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming a criminal acquittal blocks a civil suit — the lower civil standard can still find liability. Mistake: thinking only the victim can start a criminal case; the state prosecutes crimes. Exit: (a) Who brings a criminal case? (b) What is the goal of a civil case? Answers: the state / prosecution; a remedy, usually compensation."}]}'::jsonb, 'Criminal = state vs. defendant, punishment, high proof. Civil = party vs. party, compensation, lower proof. One act can trigger both.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"statute","translation":"a written law enacted by a legislature","example":"A parking fine is set by a local statute or ordinance."},{"term":"precedent","translation":"a past court decision that guides later cases with similar facts","example":"Under common law, judges follow precedent for consistency."},{"term":"jurisdiction","translation":"the authority of a court, and whose law applies, in a given place or matter","example":"Consumer rights differ by jurisdiction, so where you buy matters."},{"term":"consideration","translation":"the value each side gives in a contract — the bargained-for exchange","example":"Paying $400 for a logo is the consideration on the buyer''s side."},{"term":"negligence","translation":"a failure to use reasonable care that causes harm (a tort)","example":"An unmarked wet floor that injures a customer can be negligence."},{"term":"liability","translation":"legal responsibility to answer or pay for a wrong or harm","example":"The café faced liability for the customer''s injury."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A tort is best described as…","options":["a written statute","a civil wrong causing harm","a criminal charge","a type of court"],"answer":1,"explanation":"Torts are civil wrongs; the usual remedy is damages."},{"prompt":"The four elements of negligence are duty, breach, causation, and…","options":["intent","damages (harm)","a contract","a statute"],"answer":1,"explanation":"Without real harm, there is no negligence claim."},{"prompt":"In a criminal case, the case is brought by…","options":["the victim","the state / prosecution","an insurer","the jury"],"answer":1,"explanation":"Crimes are prosecuted by the state on behalf of the public."},{"prompt":"''Strict liability'' means a party can be liable…","options":["only if they intended harm","even without proof of fault, in certain cases","only in criminal court","only under a contract"],"answer":1,"explanation":"Some claims, like certain defective-product cases, do not require proving fault."},{"prompt":"Someone acquitted of a crime can still…","options":["never be sued for it","be found liable in a civil suit on the same facts","be retried for the same crime freely","avoid all consequences"],"answer":1,"explanation":"The civil standard (balance of probabilities) is lower than the criminal one."},{"prompt":"''Jurisdiction'' tells you…","options":["how old a law is","whose law applies and which court has authority","the price of filing","the name of the judge"],"answer":1,"explanation":"Jurisdiction determines the applicable law and the proper court — and it''s why laws vary by place."}]}'::jsonb, null, 8),
  (10, 'Applied project: analyze an everyday legal scenario', 'writing', '{"sections":[{"heading":"The task","text":"Take one ordinary situation with legal dimensions — for example: you order a product that arrives broken and the seller won''t refund; a dog off its leash bites a jogger; or you sign up for a gym and later dispute the cancellation terms. Your job is to *spot the issues*, not to give a verdict. This is a legal-literacy exercise, not legal advice, and remember the outcome would depend on your jurisdiction."},{"heading":"Milestones","text":"1) State the facts in two or three neutral sentences. 2) Identify which area(s) of law are in play — contract, tort, criminal, consumer rights, or a mix — and say why. 3) Name the parties and, if a claim were made, who would be the plaintiff and who the defendant. 4) List the key questions a court would ask (e.g., ''Was there a valid contract?'' ''Was a duty of care breached?'' ''Which standard of proof applies?''). 5) Note one way the answer might change in a different jurisdiction, and state plainly that a real decision needs a licensed lawyer."},{"heading":"Self-check rubric","text":"✔ Facts are stated neutrally, without assuming who wins. ✔ You correctly matched the situation to at least one area of law and justified it. ✔ You identified the parties and their roles. ✔ You raised the right legal questions rather than jumping to a conclusion. ✔ You acknowledged jurisdiction-dependence and framed this as literacy, not advice. If all five hold, you''re reading everyday life like an informed citizen — and you know when to call a professional."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000019' and l.position = v.pos
);
